    const ctx=canvas.getContext('2d');ctx.fillStyle=side<0?'#812d2b':'#214e7b';ctx.fillRect(0,0,256,384);
    ctx.fillStyle='#d7bd7b';ctx.beginPath();ctx.moveTo(128,55);ctx.lineTo(188,120);ctx.lineTo(128,255);ctx.lineTo(68,120);ctx.closePath();ctx.fill();
    ctx.fillStyle=side<0?'#812d2b':'#214e7b';ctx.beginPath();ctx.arc(128,150,27,0,Math.PI*2);ctx.fill();
    const tex=new THREE.CanvasTexture(canvas);tex.colorSpace=THREE.SRGBColorSpace;
