    box(side*9,1.8,20,1.2,3.6,14,stone);
    box(side*15,1.6,-12,1.2,3.2,10,brick);
    box(side*15,1.6,12,1.2,3.2,10,brick);
    // Outer flank path runs continuously from base toward mid, with frequent cover.
    box(side*19,.05,0,7.5,.25,56,floor,false);
    for(const z of [-25,-17,-9,9,17,25]){
      box(side*21.5,.9,z,1.4,1.8,1.1,stone);
      box(side*16.2,.9,z+3.2,1.1,1.8,1.6,brick);
    }
    // Upper wall walk on each flank; steps rise gradually onto it.
    box(side*25,2.35,0,3.2,.35,28,stone);
    box(side*23.35,2.75,0,.18,.7,28,pale,false);
    box(side*26.65,2.75,0,.18,.7,28,pale,false);
    for(let i=0;i<6;i++){
      const h=.38*(i+1), zz=side<0?-17+i*.75:17-i*.75;
      box(side*(20.0+i*.72),h/2,zz,1.15,h,3.0,i%2?stone:pale);
      box(side*(20.0+i*.72),h+.035,zz,1.1,.07,2.85,gold,false);
    }
    // Tall inner partitions create winding flank approaches and break long sightlines.
    box(side*12,2.6,-27,1.1,5.2,9,stone);
    box(side*12,2.6,27,1.1,5.2,9,stone);
    box(side*12,2.6,-14,1.1,5.2,5,stone);
    box(side*12,2.6,14,1.1,5.2,5,stone);
    // Wall alcoves, arrow slits and parapet merlons.
