  if(botRoot) scene.remove(botRoot); botRoot=null; bot=null;
  for(const child of [...scene.children]) if(child.userData?.temporary) scene.remove(child);
  player.x=spawnSide===1?-29.0:29.0;player.z=spawnX;player.y=1.65; jumpHeight=0;jumpVelocity=0;yaw=spawnSide===1?Math.PI/2:-Math.PI/2;pitch=0;hp=100;score=0;slowReadyAt=0;dashReadyAt=0;
